/* @author MILO-GAO(高振銘)@2020 */ package page2020.util;import java.util.Collection;import java.util.Map;public class EmptyUtil {	public static boolean is(String string) {		return (string == null || string.trim().isEmpty()) ? true : false;	}	public static boolean not(String string) {		return (! is(string));	}	public static boolean is(String... array) {		if (array == null || array.length == 0) {			return true;		}		for (String string : array) {			if (is(string)) {				return true;			}		}		return false;	}	public static boolean not(String... array) {		return (! is(array));	}	public static boolean is(Object object) {		return (object == null) ? true : false;	}	public static boolean not(Object object) {		return (! is(object));	}	public static boolean is(Object... array) {		if(array == null || array.length == 0) {			return true;		}		return false;	}	public static boolean not(Object... array) {		return (! is(array));	}	public static boolean is(int... numbers) {		if (numbers == null || numbers.length == 0) {			return true;		}		else {			return false;		}	}	public static boolean not(int... numbers) {		return (! is(numbers));	}	public static boolean is(Collection<?> collection) {		return (collection == null || collection.isEmpty()) ? true : false;	}	public static boolean not(Collection<?> collection) {		return (! is(collection));	}	public static boolean is(Map<?, ?> map) {		return (map == null || map.isEmpty()) ? true: false;	}	public static boolean not(Map<?, ?> map) {		return (! is(map));	}	public static String orEmpty(String string) {		if (not(string)) {			return string;		} else {			return "";		}	}	public static String orValue(String string, String value) {		if (not(string)) {			return string;		} else {			return value;		}	}}